  bytRet     int(10);
  bytAvl     int(10);
  reserved_1 char(8);
  actGrpMark int(10);
  actMark    int(10);
  reserved_2 char(7);
  flags      char(1);
  reserved_3 char(16);
end-ds;

//  Get Export, Returned value: Exported item - PTR(OPN)
