  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -

  // Return to caller if logging is disabled.
  if (not Logger_isWarnEnabled(i_hLogger));
    return;
  endif;

  caller.procedure = f_caller(caller.module.name
                              : caller.pgm.name
                              : caller.stmtID
                              : g_stubOfs);
  logLoggingEvent(i_hLogger: cLOG4RPG_PRIORITY_WARN
                  : %trimR(f_rtvMsgText(i_msg: *omit))
                  : caller
                  : errMsg);

  return;


end-proc;

