  pNode = i_hNode;
  pParent = i_hParent;

  node.pParent = i_hParent;

end-proc;

//=======================================================================
//  ***PRIVATE ***   (exported for internal use only)
//  Returns the parent of a given node.
//=======================================================================
//  Parameters:
//   i_hNode       - Handle of the node
//
//  Returns:
