//=======================================================================
dcl-proc Node_getParent export;
  dcl-pi *n like(LOG4RPG_hLogger_t);
    i_hNode like(LOG4RPG_hLogger_t) const;
  end-pi;

  //  Logger handle
  dcl-ds node likeds(LOG4RPG_logger_t) based(i_hNode);
