  // - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -

  g_pLayout_getFooter = layout.layoutImpl.procGetFooter.procptr;

  if g_pLayout_getFooter <> *NULL;
    footer = SrvPgmLayout_getFooter(layout.layoutImpl.pHandle);
