  if tempClassFilter.procDelete.procptr = *NULL;
    LogLog_error('Could not resolve procedure: ' +
                  proc + cFILTER_DELETE);
    return isResolved;
  endif;

  o_classFilter = tempClassFilter;

  isResolved = *on;

  return isResolved;


end-proc;

