dcl-pr XMLSocketHubAppender_childProcess;
  i_pipe      int(10) value;
  i_port      int(10) value;
  i_debugMode like(LOG4RPG_debugMode_t) value;
  i_output    like(LOG4RPG_debugOutput_t) value;
end-pr;

//  Initializes client sockets.
dcl-pr initClients;
  io_clients int(10) dim(cMAX_CLIENTS);
end-pr;

//  Forward data to clients.
dcl-pr doCLients;
  io_clients int(10) dim(cMAX_CLIENTS);
  i_writeSet like(socket_fdSet_t) const;
  i_pBuffer  pointer const;
  i_length   int(10) const;
end-pr;

//  Closes client sockets.
dcl-pr closeClients;
  io_clients int(10) dim(cMAX_CLIENTS);
end-pr;

//  Closes client socket.
