//  Error code
dcl-c SOCKET_ERROR -1;

//  Socket NULL
dcl-c SOCKET_NULL -2;

// -----------------------------------------
//  Constants:   QSYSINC/NETINET.IN
// -----------------------------------------

//  Macros to denote protocols
