//  Macros to denote type of socket
dcl-c SOCK_STREAM 1;
dcl-c SOCK_DGRAM 2;
dcl-c SOCK_RAW 3;
dcl-c SOCK_SEQPACKET 5;

//  Macros for socket level options (via setsockopt() & getsockopt())
dcl-c SO_BROADCAST 5;
dcl-c SO_DEBUG 10;
