//  Constants:   QSYSINC/H.FCNTL
// -----------------------------------------

//  cmd Values for fcntl()
dcl-c F_DUPFD 0;
dcl-c F_GETFD 1;
dcl-c F_SETFD 2;
dcl-c F_GETLK 3;
dcl-c F_SETLK 4;
dcl-c F_SETLKW 5;
dcl-c F_GETFL 6;
dcl-c F_SETFL 7;
dcl-c F_GETOWN 8;
dcl-c F_SETOWN 9;

